package com.fream.back.domain.m64.p02;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fream.back.domain.m64.dto.p19.Xjt45InfoCreateDto;
import com.fream.back.domain.m64.entity.Xjt45Info;
import com.fream.back.domain.m64.exception.Xjt45ApiException;
import com.fream.back.domain.m64.exception.Xjt45ErrorCode;
